void TileSetAtlasSourceEditor::TileSetAtlasSourceProxyObject::set_id(int r_id) {
	ERR_FAIL_COND(r_id < 0);
	if (source_id == r_id) {
		return;
	}
	ERR_FAIL_COND_MSG(tile_set->has_source(r_id), vformat("Cannot change TileSet Atlas Source ID. Another source exists with id %d.", r_id));

	int previous_source = source_id;
	source_id = r_id; // source_id must be updated before, because it's used by the source list update.
	tile_set->set_source_id(previous_source, r_id);
	emit_signal(CoreStringName(changed), "id");
}
